import{_ as t,H as a,f as A,i}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"开篇词 | AI+前端：开启未来发展的新篇章","description":"","frontmatter":{},"headers":[{"level":2,"title":"前端 +AI 是大势所趋","slug":"前端-ai-是大势所趋","link":"#前端-ai-是大势所趋","children":[]},{"level":2,"title":"AI 对于我们有何帮助","slug":"ai-对于我们有何帮助","link":"#ai-对于我们有何帮助","children":[]},{"level":2,"title":"如何学？","slug":"如何学","link":"#如何学","children":[]}],"relativePath":"前端工程师的AI实战课/开篇词｜AI+前端：开启未来发展的新篇章.md","filePath":"前端工程师的AI实战课/开篇词｜AI+前端：开启未来发展的新篇章.md","lastUpdated":1795542204000}'),p={name:"前端工程师的AI实战课/开篇词｜AI+前端：开启未来发展的新篇章.md"};function I(n,e,r,s,E,l){return a(),A("div",null,[...e[0]||(e[0]=[i('<h1 id="开篇词-ai-前端-开启未来发展的新篇章" tabindex="-1">开篇词 | AI+前端：开启未来发展的新篇章 <a class="header-anchor" href="#开篇词-ai-前端-开启未来发展的新篇章" aria-label="Permalink to &quot;开篇词 | AI+前端：开启未来发展的新篇章&quot;">​</a></h1><p>你好，我是柳博文，欢迎来到前端工程师的 AI 实战课。</p><p>我算是国内探索 AI+ 前端领域比较早的一拨人。在各种大模型产品受到广泛关注之前，就已经开始尝试 AI 出码、UI 千人千面等诸多方式，帮助前端工程师提效，也给产品创新带来更多可能。</p><p>我曾有两段工作经历和 AI 紧密相关，现在回想起来感觉自己还挺幸运的。</p><p>一个是在腾讯游戏的数据平台，主要做 Web 端游戏视频的智能剪辑功能研发。这让我深入了解了如何利用 AI 技术优化剪辑效果，提升视频内容的质量，给用户带来更好的观看体验。这也是我开始接触并思考端侧模型的开始。</p><p>另一个是淘宝的营销前台，主要做手机淘宝的导购营销，在这个过程中，有两个实践是我印象最深刻的。第一个是在工程链路上结合 AI 来实现自动出码，提升研发效率。第二个就是在用户体验层面探索 AI 驱动的人群精细化 UI 运营，提升业务转化。这使我进一步深化了自己对“AI+ 前端”的认识。</p><p>后来，随着 ChatGPT 和 Copilot 等代表性产品的出现和热度上升，我们再一次体会到了 AI（尤其是大模型）的强大。</p><h2 id="前端-ai-是大势所趋" tabindex="-1">前端 +AI 是大势所趋 <a class="header-anchor" href="#前端-ai-是大势所趋" aria-label="Permalink to &quot;前端 +AI 是大势所趋&quot;">​</a></h2><p>这些经历，都让我更加看好 AI + 前端这个领域。就像 NodeJS 让前端经历了一次很大的跨越，我认为前端同样会因为 AI 的推动，再一次出现巨大的创新和发展。</p><p>我觉得前端结合 AI，是一种必然趋势。</p><p>随着智能技术的飞速发展，AI 已经在各个领域展现出巨大的潜力和影响力。前端作为用户与网站或应用交互的直接界面，引入 AI 技术可以极大地提升用户体验和应用的智能化水平。这是技术进步带来的必然趋势，也是前端开发领域适应未来发展的重要方向。</p><p>有需求就会有竞争。在现代社会，用户对于个性化、智能化的服务需求日益增长。前端开发融入 AI 技术，可以更好地满足这些需求，提升产品的市场竞争力。同时，随着越来越多的企业开始关注并投入 AI 技术的研发和应用，掌握 AI 技能的前端开发者也将更具市场竞争力。</p><h2 id="ai-对于我们有何帮助" tabindex="-1">AI 对于我们有何帮助 <a class="header-anchor" href="#ai-对于我们有何帮助" aria-label="Permalink to &quot;AI 对于我们有何帮助&quot;">​</a></h2><p>再说回到 A 对于前端同学有哪些帮助。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84AI%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84AI%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" alt=""></a></p><p>结合我的实践经验，直观的感受就是能够提升开发效率。AI 技术可以帮助前端同学自动完成一些重复性高、模式化的工作，如代码生成、错误检测等。这不仅可以减轻我们的工作负担，还可以显著提升开发效率，使得开发者有更多的时间和精力专注于更具创新性和挑战性的任务。</p><p>在实际开发中，掌握 AI 技术还能让我们在解决复杂问题时更加游刃有余。AI 能够帮助前端工程师优化性能，例如通过智能预测与数据缓存技术，减少用户的等待时间，提升应用的响应速度。</p><p>更重要的是，AI 的引入能帮助前端处理更复杂的交互逻辑。在这个过程里，我们也能不断提升自己的技术能力，更深层次地参与产品整体设计与开发。比如借助 AI，我们就能实现个性化推荐、智能搜索、动态内容生成等功能，给用户带来更加优质的服务体验，这是未来互联网产品做大做强的必然方向。</p><p>总结来说就是，掌握 AI 技术，不仅能让前端工程师在求职市场上更具竞争力，更能让我们成长为全能型技术人才，推动产品创新和技术升级，满足用户日益增长的智能化需求。因此，对于前端工程师，学习 AI 不仅是紧跟技术潮流的必然选择，更是加速个人成长、提升竞争力的有效途径。</p><h2 id="如何学" tabindex="-1">如何学？ <a class="header-anchor" href="#如何学" aria-label="Permalink to &quot;如何学？&quot;">​</a></h2><p>那么我们如何走进前端 +AI 这个领域，掌握其中的关键技术呢？我和很多前端小伙伴讨论这个问题的时候，发现最集中的困难就是这么两类。</p><p>一类是缺少相关理论基础，过不了 AI 原理关，即使想学习，也会迷失在庞杂的 AI 资料里无所适从。另一类就是动手实践关。对于怎么应用 AI 赋能日常的研发和业务，也可能没什么头绪。因为没有实践场景，即使初步掌握了一些 AI 技术也无法落地，长此以往就会打击我们的学习积极性。</p><p>针对这些困扰，我把自己的过往经验做了抽象和总结，希望通过这门课程来帮助更多前端同学了解 AI，并进一步深入到 AI+ 前端这个新方向。</p><p>这门课的知识导图如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84AI%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%89%8D%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84AI%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.jpeg" alt=""></a></p><p>先来看第一章，我会为你梳理一下后续课程会用到的前端知识（React 和 NodeJS），组件化及组件可解释性。这部分内容既是对我们熟悉的领域做个快速回顾，也是我们后续实践的前置基础。</p><p>第二章我们来打通原理关。我会站在前端工程师的视角，带你掌握必要的视觉 AI 技术基础。为了让理论学习不那么枯燥，我们还会实践使用 JS 版本的视觉模型，通过动手完成各种 AI基础实例巩固所学，还会学习如何部署模型运行环境，并通过实验掌握数据整理、模型训练、验证和预测的技能。</p><p>有了前面的基础，第三章我们来实现一个 AI 布局助手，体验从 AI 模型的训练到自动出码的全过程。完成这个项目后，你将掌握数据集收集、增广、标签制作，模型训练与指标观察，组件识别及分析等技术，相信这些也会激发你对 AI+ 前端创新实践的更多灵感。</p><p>第四章我们会结合 AI 进行另外一个实践，基于 AI 的 Feeds 流端侧重排。这个项目能让我们更深刻地体验到 AI 如何作用于真实的业务场景，掌握热力图工具以及数据可视化分析，通过AI 算法模型推荐实现人群精细化 UI 运营等新技能，为业务提效带来新思路。</p><p>最后在第五章，我们将进行一些开源项目的本地搭建尝试，搭建本地大模型应用矩阵。学习、部署开源的 ChatGLM2-6B 项目，实现文本大模型助手。随后，通过学习与部署StableDiffusion 来体验文生图大模型，实现图像生成大模型本地应用。最后，学习探讨视频生成大模型，并通过 MuseTalk 进行体验。</p><p>总之，希望这门课能给你带来技术和经验的双重收获。技术方面，让你掌握初步学习 AI 技术的方法，掌握 AI+ 前端开发新范式，熟悉数据制作到模型训练、代码生成的全流程。经验方面，通过大厂前端领域和商业场景中的 AI 落地经验传递，激发你的更多实践灵感。</p><p>最后想说的是，前端的发展早已经进入深水区，“AI+ 前端”无疑会成为前端深水区之一，在 AI大模型爆发的这个关键节点进入这个领域，无疑也是一个不错的选择。机会属于有心人，让我们一起加油吧！</p><p>代码库连接： <a href="https://github.com/IrvingBB/geektime_AIFE" target="_blank" rel="noreferrer">https://github.com/IrvingBB/geektime_AIFE</a></p>',33)])])}const _=t(p,[["render",I]]);export{h as __pageData,_ as default};
